{
  "model": "mistral:7b",
  "prompt": "Parse this Google Pay transaction email and return ONLY a valid JSON object with these exact keys: amount (number), payee (string), type (debit or credit or transfer), date (YYYY-MM-DD), category (groceries/transport/entertainment/medical/utilities/shopping/food/transfer/salary/other), description (brief one line). Do not include any explanation.\n\nEmail subject: You paid Rs. 500.00 to Amazon\nEmail body: You have successfully paid Rs. 500.00 to Amazon via Google Pay. Transaction ID: TXN123456789. Date: 02 Jun 2026 14:30:00 IST. Your account balance is Rs. 15,230.50.",
  "stream": false,
  "options": { "temperature": 0.1, "num_predict": 200 }
}

={
  "title": "GPay: {{ JSON.parse($json.response).type }} ₹{{ JSON.parse($json.response).amount }} to {{ JSON.parse($json.response).payee }}",
  "content": "Subject: You paid Rs. 500.00 to Amazon\nBody: You have successfully paid Rs. 500.00 to Amazon via Google Pay.\n\nParsed: {{ $json.response }}"
}
